"""The active design guide and palette documentation follow main.css tokens."""
import re

def build_brand_guide(ctx):
 S=ctx['SITE'];DATA=ctx['DATA'];E=ctx['E'];emit=ctx['emit'];icon=ctx['icon'];link=ctx['link'];ed=ctx['editable']
 css=(S/'css/main.css').read_text();root=re.search(r':root\s*\{(.*?)\}',css,re.S)[1];values=dict(re.findall(r'--([\w-]+):\s*(#[0-9a-fA-F]{6})\s*;',root))
 def lum(c):
  x=[int(c[i:i+2],16)/255 for i in(1,3,5)];return sum(w*(v/12.92 if v<=.04045 else((v+.055)/1.055)**2.4)for w,v in zip([.2126,.7152,.0722],x))
 def contrast(a,b):x,y=sorted([lum(values[a]),lum(values[b])]);return(y+.05)/(x+.05)
 rows=DATA['brand_palette'];swatches=''.join(f'<article class="brand-swatch"><div class="brand-swatch-colour" style="--swatch:var(--{p["token"]})" aria-hidden="true"></div><h3>{E(p["label"])}</h3><code>--{p["token"]} · {values[p["token"]].upper()}</code><p>{E(p["role"])}</p><p class="brand-rule">{E(p["avoid"])}</p></article>'for p in rows)
 body='<section class="section inner-section" id="palette"><div class="container"><div class="section-head"><h2>Палитра и роли</h2></div><div class="brand-swatch-grid">'+swatches+'</div></div></section>'
 body+='<section class="section inner-section cream-section"><div class="container"><div class="section-head"><h2>Знак и логотип</h2></div><div class="brand-logo-examples"><div><img src="img/'+DATA['branding']['logo']+'" alt="Цветной логотип Манго Путешествия" width="1193" height="440" loading="lazy" data-editable="brand.logo"><p>Светлая и компактная шапка</p></div><div class="brand-logo-dark"><img src="img/'+DATA['branding']['light']+'" alt="Светлый логотип Манго Путешествия" width="1193" height="440" loading="lazy" data-editable="brand.light"><p>Шапка поверх фото и подвал</p></div></div></div></section>'
 pairs=[('cream','clay','Текст основной кнопки'),('clay','cream','Красная ссылка на кремовом'),('clay','sand','Красная ссылка на песочном'),('sage','cream','Мелкий зелёный на кремовом'),('sage','sand','Зелёный на песочном — для мелкого текста нельзя'),('muted','sand','Вторичная подпись на песочном'),('footer-text','footer','Текст подвала'),('mango','cream','Оранжевый на светлом — только декор'),('leaf','cream','Лист на светлом — только декор')]
 table='<div class="brand-table-wrap"><table class="brand-table"><caption>Контраст сплошных цветов</caption><thead><tr><th scope="col">Сочетание</th><th scope="col">Контраст</th><th scope="col">Мелкий текст</th></tr></thead><tbody>'+''.join(f'<tr><th scope="row">{E(label)}</th><td>{contrast(a,b):.2f}:1</td><td>{"AA"if contrast(a,b)>=4.5 else"Недопустим"}</td></tr>'for a,b,label in pairs)+'</tbody></table></div>'
 body+='<section class="section inner-section"><div class="container"><div class="section-head"><h2>Доступность и компоненты</h2></div>'+table+'<div class="brand-components"><a class="btn btn-primary" href="#contact" data-goal="guide_primary">Подобрать отдых '+icon('i-arrow')+'</a><a class="rest-pill rest-pill-outline" href="#palette" data-goal="guide_secondary">Посмотреть палитру</a><span class="brand-leaf-example" aria-hidden="true">'+icon('i-mood-mountains')+'</span></div><p class="section-description">Оранжевый не используется для текста на светлом фоне. Зелёный листа служит декором; мелкие зелёные подписи набраны более тёмным sage. Подписи на песке используют muted или muted-on-sand. Для фотографии контраст проверяется вместе с затемнением.</p></div></section>'
 emit('styleguide.html','Дизайн-система — Манго Путешествия, Астрахань','Логотип, палитра и компоненты актуального дизайна Манго Путешествия: доступные сочетания, правила цветов и типографика.','Дизайн-система Манго','Cormorant Garamond, Manrope, светлый песок и цвета нового знака.',body,[('Дизайн-система',None)],'Вопрос по оформлению',assets=['css/brand-guide.css'])
 doc='# Дизайн 1 · актуальная система Mango Travel\n\nСветлый, спокойный интерфейс: песок и крем, крупный Cormorant Garamond и ясный Manrope. Цветной SVG используется на светлом, светлый — поверх фото и в тёмном подвале. Новый логотип имеет размеры 1193 × 440; шапка 54 px, компактная 42 px, телефон 40 px, подвал 56 px. Логотип центрирован на компьютере, пункты меню отстоят от его реальной ширины симметрично.\n\n## Палитра\n\nИсточник истины — css/main.css, :root. Все компонентные стили используют переменные, включая RGB-каналы прозрачностей. Ключ clay сохранён для совместимости компонентов, теперь это красный логотипа.\n\n| Токен | HEX | Роль | Ограничение |\n|---|---|---|---|\n'+''.join(f'| --{p["token"]} | {values[p["token"]].upper()} | {p["role"]} | {p["avoid"]} |\n'for p in rows)
 doc+='\n## Контраст\n\n'+''.join(f'- {label}: {contrast(a,b):.2f}:1.\n'for a,b,label in pairs)+'\nМелкий текст требует 4,5:1, крупный — 3:1. Mango и leaf не применяются к мелкому тексту на светлом фоне. Вторичный muted затемнён до '+values['muted'].upper()+', чтобы сохранить AA на sand. Sage остаётся заданным #5C7042: мелкий текст на кремовом проходит, на sand — нет. У disabled-кнопок читаемый нейтральный текст; активные состояния сохраняют красный акцент. Под фото используется нейтральное тёмное затемнение со стороны текста и снизу; правая часть фотографии остаётся светлой.\n\n## Типографика, сетка и движение\n\nCormorant Garamond для заголовков, Manrope для текста, локальные WOFF2 с кириллицей. Контейнер до 1280 px, поля 22/42/60 px, карточки 18 px. Фотокарточки отдыха 16:10, на телефоне свайп; предложения 3/2/1. Предпочтение reduced motion отключает декоративное движение. Слайдер переключается только вручную: стрелки, свайп, текстовый счётчик и название следующего слайда. Автосмена, прогресс и точки не используются.\n\n## Примеры и отели\n\nПроверки отелей сохраняют отдельные блоки «Например»: манговый tint, тонкая оранжевая левая линия, тёмный курсив Cormorant. Над вкладками отелей отдельных примеров больше нет: подсказки из исходников находятся внутри карточек после «Чем хорош» и «Что учесть». Они остаются редактируемыми и требуют проверки до публикации.\n\nЭкскурсионную карточку иллюстрирует Эйфелева башня, а не остров. Источник и лицензия — img/sources.json. Реальной отправки форм нет; данные очищаются после локальной проверки.\n'
 (S/'DESIGN.md').write_text(doc+'\n## Онлайн-агентство и связь\n\nАстрахань · работаем онлайн по всей России. Публичного адреса офиса нет; юридический адрес заполняется только в реквизитах. Единый шаблон формы имеет три набора полей: подбор, предложение и отдельная услуга. После полей — MAX и Telegram. В сообщение входят тема и параметры поездки, телефон исключён. Компактные страницы услуг сохраняют три смысловые колонки; вместо общей формы в конце стоит полоса обращения. Посадочный талон используется только для предложений: фото, перфорация, маршрут и детали поездки; в других компонентах этот приём не повторяется. Команда объединена со страницей О нас.\n')

 # Keep the technical accent comparison on the same icon set without changing its copy.
 archive=S/'accent-options.html'
 if archive.exists():
  html=archive.read_text()
  html=re.sub(r'<link[^>]+rel="(?:icon|alternate icon|apple-touch-icon)"[^>]*>','',html)
  html=html.replace('</head>',ctx['brand_icons']('accent-options.html')+'</head>')
  html=re.sub(r'<span class="brand-name">.*?</span>','<img src="img/'+DATA['branding']['light']+'" alt="Манго Путешествия" width="1193" height="440" data-editable="brand.light">',html,flags=re.S)
  archive.write_text(html)
